  const knee0: [number, number, number] = [m * 0.6 * spread, 0.14 - LEG_BACK, 1.1792 * zk];
  const ankle0: [number, number, number] = [m * 0.58 * spread, -0.02 - LEG_BACK, 0.26];
  const Lt9 = legLenD9(hip, knee0);
  const Ls9 = legLenD9(knee0, ankle0);
