      const HG_T0 = 0.22; const HG_T1 = 0.89;   // 아가리 높이 — 낯의 3분의 2(요청)
      const HG_S9 = 0.75;                       // 아가리 반폭 — 낯의 4분의 3(요청)
      const hgTX9 = Math.cos(HG_A9); const hgTY9 = -Math.sin(HG_A9);   // 낯의 좌우 자
