      const hgWall9 = (t0: number, t1: number, s0: number, s1: number): ShapeFace =>
        bodyFace(polyPath3([hgAt9(t0, s0, 0), hgAt9(t0, s1, 0), hgAt9(t1, s1, 0), hgAt9(t1, s0, 0)]));
