        const dz0 = BODY_Z0 + BODY_H * 0.46; const dz0z9 = BODY_Z0z9 + BODY_H * 0.5152; /* z용 쌍둥이(model-z-scale ×0.8) */
        const dz1 = BODY_Z0 + BODY_H - 0.16; const dz1z9 = BODY_Z0z9 + BODY_Hz9 - 0.1792; /* z용 쌍둥이(model-z-scale ×0.8) */
        const dh = dz1 - dz0;
