    const RIM_HH9 = 0.17;
    const rim9 = (far9: boolean): ShapeFace[] => [
      ...hoop9(far9, RING_R + BAND_TH9 + 0.04, PY_M + RING_HH9 - RIM_HH9, RIM_HH9, CLAW9),
      ...hoop9(far9, RING_R + BAND_TH9 + 0.04, PY_M - RING_HH9 + RIM_HH9, RIM_HH9, CLAW9),
    ];
