      const at9 = (x9: number, a9: number, s9: number): [number, number, number] =>
        [x9, CY + Math.cos(a9) * RIM * GEAR_WK9 * s9, CZ + Math.sin(a9) * RIM * kZ9 * s9];
      /** 화면 자로 잰 바퀴 반지름 — 이빨 높이·둘레 마디 수를 정하는 데만 쓴다. */
      const R9 = RIM * Lz9 * kZ9;
      /** 가까운 판 — 화가 순서(먼 판 → 옆벽 → 가까운 판)의 기준이다. */
      const nearIs0 = depthNow(WX0, CY) >= depthNow(WX1, CY);
      const nx9 = nearIs0 ? WX0 : WX1;
      const fx9 = nearIs0 ? WX1 : WX0;
      /** 드러난 판의 명암은 세계 광원이 정한다(요청: 돌려도 광원 고정). */
      const nearLit = faceLight(nearIs0 ? -1 : 1, 0);
      const TN = 10;                       // 이빨 수
      const TH = R9 * 0.1;                 // 이빨 높이(화면 자) — 0.32 → 0.1(2026-10-13, 요청: "포지 톱니바퀴의 이빨들 높이 아주 낮게 납작하게")
      const TW = (Math.PI / TN) * 0.42;    // 이빨 반각
