      const PHL9 = 0.92 * PW9;                // 반 길이 — 판이 넓어진 몫을 그대로 탄다
      const PZ9 = PAD_H9;                     // 발판 윗면
      const PF9 = Math.min(0.45, (PR9 / (2 * PHL9)));   // 끝을 여미는 몫
      const [pax9, pay9] = at9(sr9(3.5), -PHL9);
