      const dx9 = ARM_LEAN9 / dn9; const dz9 = 1 / dn9;      // 곧은 몫의 방향(바깥·위)
      const nx9 = -1 / dn9; const nz9 = ARM_LEAN9 / dn9;     // 그 왼쪽 법선(안·위) — U 의 중심 쪽
      const aX9 = r09 * DK9 + ARM_STR9 * ARM_LEAN9;          // 곧은 몫 끝(화면 x)
      const aZ9 = pz9 + ARM_STR9;
      /** U 반지름 — 끝 반지름에서 거꾸로 푼다(위 ★: 가로 몫의 합이 곧 이 식이다). */
      const UR9 = ((aX9 - ARM_R19 * DK9) * dn9 - ARM_TAIL9 * ARM_LEAN9) / 2;
      const ucX9 = aX9 + UR9 * nx9; const ucZ9 = aZ9 + UR9 * nz9;   // U 의 중심
      const eX9 = aX9 + 2 * UR9 * nx9; const eZ9 = aZ9 + 2 * UR9 * nz9;   // U 를 돈 자리
      /* t 는 **길이 몫**으로 나눈다 — 세 토막이 제 길이만큼 마디를 가져가야 관이 고르게 굽는다. */
      const l19 = ARM_STR9 * dn9; const l29 = Math.PI * UR9;
      const lt9 = l19 + l29 + ARM_TAIL9;
      const ARM_TS9 = l19 / lt9;                 // 곧은 몫이 차지하는 t
      const ARM_TU9 = (l19 + l29) / lt9;         // U 가 끝나는 t
      const pipe9 = (t9: number): [number, number, number] => {
        if (t9 <= ARM_TS9) {
          const u9 = t9 / ARM_TS9;
          return P9((r09 * DK9 + (aX9 - r09 * DK9) * u9) / DK9, pz9 + ARM_STR9 * u9);
        }
        if (t9 <= ARM_TU9) {
          const ph9 = ((t9 - ARM_TS9) / (ARM_TU9 - ARM_TS9)) * Math.PI;
          const c9 = Math.cos(ph9); const s9 = Math.sin(ph9);
          const vx9 = -UR9 * nx9; const vz9 = -UR9 * nz9;   // 중심에서 본 곧은 몫 끝
          return P9((ucX9 + vx9 * c9 - vz9 * s9) / DK9, ucZ9 + vx9 * s9 + vz9 * c9);
        }
        const u9 = (t9 - ARM_TU9) / (1 - ARM_TU9);
        return P9((eX9 - ARM_TAIL9 * dx9 * u9) / DK9, eZ9 - ARM_TAIL9 * dz9 * u9);
      };
      const ak9 = K(cx9 * 4.4, cy9 * 4.4, 3);
      // ⓐ 파이프 — 가는 관.
      out.push(...tagKey(paintBase(spirePillar({
        /* ⚠ 마디는 **U 가 차지하는 몫**으로 고른다 — 반원이 길이의 반을 넘게 가져가므로 12 로는
           한 마디가 26도라 U 가 각진 고리로 읽힌다(22 이면 16도). */
        x: 0, y: 0, h: 0.8, w: 0.3, tipW: 0.3, segs: 22, sides: 8, hold: 1, caps: "none",
        path: pipe9,
      }), GOLD_D), ak9));
      /* ⓑ 감싸개 — 파이프의 2/3 을 도는 금색 통(아래가 가늘고 위가 두껍다) + 위 끝의 임자색 띠. */
      /* ★ 감싸개의 자는 **덮는 높이(z)** 다(재요청: "감싸개 높이는 지금의 2배" — 0.88 → 1.76) — t 로 적어 두면
         곧은 몫을 늘릴 때마다 감싸개가 저 혼자 따라 늘어난다. 높이로 두고 t 를 거기서 푼다(곧은 몫 안에서
         `z = t/ARM_TS9 · ARM_STR9`). 곧은 몫 2.30 의 77% 를 덮으므로 감싸개 뒤에 맨 관이 0.54 남는다. */
      const SLV_Z9 = 1.76;
      const SLV_T9 = Math.min(ARM_TS9 - 0.01, 0.04 + (SLV_Z9 / ARM_STR9) * ARM_TS9);
      const SLV_B9 = SLV_T9 - 0.08;
      const sleeve9 = (u09: number, u19: number, fill9?: string): ShapeFace[] => spirePillar({
        x: 0, y: 0, h: 0.8, w: 1, segs: Math.max(3, Math.round((u19 - u09) * 24)),
        sides: 10, caps: "none", trueNormal: true,
        path: (t9: number): [number, number, number] => pipe9(u09 + (u19 - u09) * t9),
        widthOf: (t9: number): number => {
          const u9 = u09 + (u19 - u09) * t9;
          return 0.30 + 0.24 * (u9 / SLV_T9);
        },
        ...(fill9 ? { fill: fill9 } : {}),
      });
      out.push(...tagKey(sleeve9(0.04, SLV_B9, GOLD), ak9 + 0.1));
      /* ★ 감싸개의 **윗면을 막는다**(2026-09, 요청: "파이프 감싸개 윗면 임자색으로 막아주기") —
         `caps: "none"` 이라 끝이 뚫려 관 속이 비쳤다. 그 자리의 단면(접선에 수직인 원반)을 손수
         덮는다 — spirePillar 의 틀과 같은 자(u = ẑ 를 접선에 수직화 · v = T×u)로 낸다. */
      /** 그 t 에서 파이프에 수직인 두 축 — spirePillar 의 틀과 같은 자(u = ẑ 수직화 · v = T×u). */
      const frame9 = (t9: number): [number[], number[]] => {
        const e9 = 0.004;
        const p19 = pipe9(Math.max(0, t9 - e9)); const p29 = pipe9(Math.min(1, t9 + e9));
        const d9 = [p29[0] - p19[0], p29[1] - p19[1], p29[2] - p19[2]];
        const l9 = Math.hypot(d9[0], d9[1], d9[2]) || 1;
        const T9 = [d9[0] / l9, d9[1] / l9, d9[2] / l9];
        const dot9 = T9[2];
        let u9 = [-T9[0] * dot9, -T9[1] * dot9, 1 - T9[2] * dot9];
        const ul9 = Math.hypot(u9[0], u9[1], u9[2]) || 1;
        u9 = [u9[0] / ul9, u9[1] / ul9, u9[2] / ul9];
        return [u9, [T9[1] * u9[2] - T9[2] * u9[1], T9[2] * u9[0] - T9[0] * u9[2],
          T9[0] * u9[1] - T9[1] * u9[0]]];
      };
      const slvCap9 = ((): ShapeFace[] => {
        const [u9, v9] = frame9(SLV_T9);
        const c9 = pipe9(SLV_T9); const r9 = 0.30 + 0.24;
        return [bodyFace(polyPath3(Array.from({ length: 10 }, (_, j9) => {
          const th9 = (j9 / 10) * Math.PI * 2 + Math.PI / 10;
          const cu9 = Math.cos(th9) * r9; const sv9 = Math.sin(th9) * r9;
          return [c9[0] + u9[0] * cu9 + v9[0] * sv9, c9[1] + u9[1] * cu9 + v9[1] * sv9,
            c9[2] + u9[2] * cu9 + v9[2] * sv9] as [number, number, number];
        })))];
      })();
      /* ★ **마루를 보석 구슬 셋이 두른다**(2026-09, 요청: "각 파이프 꺾인 후 부분의 중앙쯤에 작은
         보석구슬 세개씩 둘러 붙이기" → 재요청: "크기 1.5배하고 위치를 위쪽 잘 보이는 곳으로 좀
         모으기") — 파이프에 **수직인 틀**(frame9)로 120도마다 하나씩 살에 반쯤 물려 앉힌다.
         ⚠ 자리는 손 값(옛 t 0.88)이 아니라 **마루 그 자리**(높이가 가장 높은 t 를 훑어 찾는다)다:
         부감 40도에서 가장 잘 보이는 자리이고, U 의 자(UR9·ARM_STR9)를 고쳐도 구슬이
         저절로 마루에 남는다. */
