    out.push(...tagKey(paintBase(cylinderFaces3(0, 0, 0.34, COMSAT_MAST_H9, COMSAT_MAST_Z09), TERRAN_STEEL),
      26 + depthNow(0, 0)));
    /* 오른뒤 마디진 작은 탑(사진) — 테가 층층이 끼워진 가는 기둥. */
