    const GD9: [number, number, number] = [gyS9 * gLen9 + carry9 * 0.3, gyC9 * gLen9, at ? 0 : 0.38 + carry9 * 0.624];   // 총 축 방향(걸을 땐 총구가 대각선 위로 · 쏠 땐 수평)
