    crater(-0.7, 0.4, 2.4, 1.56, depthNow(-0.7, 0.4) * 1.6 + 0.2);
    crater(3.0, -2.1, 1.85, 1.4, depthNow(3.0, -2.1) * 1.6 + 0.2, 0.5);   // 반 바퀴 뒤 — 큰 분화구가 쉴 때 낸다
