  mk: (tag: string) => BakeCv9;
  /** 잘라 담을 판(w×h) — 메인은 창고(takeStored9)에서 먼저 꺼낸다. */
  out: (w: number, h: number, tag: string) => BakeCv9;
  /** 빌림터 한 장 상한·빌림터 총량(바이트) · 판 한 변 상한 */
