        const a2 = angOf(qx, qy);
        const TAU = Math.PI * 2;
        const norm9 = (a9: number): number => ((a9 % TAU) + TAU) % TAU;
        const span = sf === 1 ? norm9(a2 - a1) : norm9(a1 - a2);
